module Engine.Coroutine where

import Engine.Container
import Engine.Type
import qualified Data.Foldable as DF
import qualified Data.IntMap as DIM
import qualified Data.IntSet as DIS
import qualified Data.Sequence as DS

init_coroutine_state::Widget a->Coroutine_state a
init_coroutine_state widget=Coroutine_state {widget=widget,variable=DIM.empty,program_counter=DIM.singleton 0 (Program_counter {code_index=0,clone_index=0}),index_group=DIM.empty,main_index_group=DS.singleton 0,index_group_index=0,program_counter_index=1}

to_coroutine::Raw_coroutine a ()->Coroutine a
to_coroutine raw_coroutine=let coroutine_sequence=raw_coroutine.coroutine_sequence in case coroutine_sequence of
    DS.Empty->Done
    coroutine DS.:<| other_coroutine->if DS.null other_coroutine then coroutine else Then {coroutine_sequence=coroutine_sequence}

lift_coroutine::Coroutine a->Raw_coroutine a ()
lift_coroutine coroutine=Raw_coroutine {coroutine_sequence=DS.singleton coroutine,value=()}

do_empty::Raw_coroutine a ()
do_empty=Raw_coroutine {coroutine_sequence=DS.empty,value=()}

do_emit::(Engine a->Widget a->(Widget a,Engine a))->Raw_coroutine a ()
do_emit emit=lift_coroutine (Emit {emit=emit})

do_wait::Dynamic_int a->Raw_coroutine a ()
do_wait dynamic_int=lift_coroutine (Wait {dynamic_int=dynamic_int})

do_forever::Raw_coroutine a ()->Raw_coroutine a ()
do_forever raw_coroutine=lift_coroutine (Forever {coroutine=to_coroutine raw_coroutine})

do_then::Raw_coroutine a ()->Raw_coroutine a ()
do_then raw_coroutine=let coroutine_sequence=raw_coroutine.coroutine_sequence in case coroutine_sequence of
    DS.Empty->do_empty
    coroutine DS.:<| other_coroutine->if DS.null other_coroutine then lift_coroutine coroutine else lift_coroutine (Then {coroutine_sequence=coroutine_sequence})

do_while::Dynamic_bool a->Raw_coroutine a ()->Raw_coroutine a ()
do_while dynamic_bool raw_coroutine=lift_coroutine (While {dynamic_bool=dynamic_bool,coroutine=to_coroutine raw_coroutine})

do_pause::Dynamic_bool a->Raw_coroutine a ()->Raw_coroutine a ()
do_pause dynamic_bool raw_coroutine=lift_coroutine (Pause {dynamic_bool=dynamic_bool,coroutine=to_coroutine raw_coroutine})

do_skip::Dynamic_bool a->Raw_coroutine a ()->Raw_coroutine a ()
do_skip dynamic_bool raw_coroutine=lift_coroutine (Skip {dynamic_bool=dynamic_bool,coroutine=to_coroutine raw_coroutine})

do_repeat::Dynamic_int a->Raw_coroutine a ()->Raw_coroutine a ()
do_repeat dynamic_int raw_coroutine=lift_coroutine (Repeat {dynamic_int=dynamic_int,coroutine=to_coroutine raw_coroutine})

do_clone::Int->Raw_coroutine a ()->Raw_coroutine a ()
do_clone int raw_coroutine=lift_coroutine (Clone {int=int,coroutine=to_coroutine raw_coroutine})

do_if::Dynamic_bool a->Raw_coroutine a ()->Raw_coroutine a ()->Raw_coroutine a ()
do_if dynamic_bool first_raw_coroutine second_raw_coroutine=lift_coroutine (If {dynamic_bool=dynamic_bool,first_coroutine=to_coroutine first_raw_coroutine,second_coroutine=to_coroutine second_raw_coroutine})

do_dynamic_clone::Dynamic_int a->Int->Raw_coroutine a ()->Raw_coroutine a ()
do_dynamic_clone dynamic_int int raw_coroutine=lift_coroutine (Dynamic_clone {dynamic_int=dynamic_int,int=int,coroutine=to_coroutine raw_coroutine})

do_case::Dynamic_int a->Raw_coroutine a ()->Raw_coroutine a ()
do_case dynamic_int raw_coroutine=let coroutine_sequence=raw_coroutine.coroutine_sequence in case coroutine_sequence of
    DS.Empty->do_empty
    coroutine DS.:<| other_coroutine->let int=DS.length other_coroutine in if int==0 then lift_coroutine coroutine else lift_coroutine (Case {dynamic_int=dynamic_int,int=int+1,coroutine_sequence=coroutine_sequence})

do_fork::Raw_coroutine a ()->Raw_coroutine a ()
do_fork raw_coroutine=let coroutine_sequence=raw_coroutine.coroutine_sequence in case coroutine_sequence of
    DS.Empty->do_empty
    coroutine DS.:<| other_coroutine->let int=DS.length other_coroutine in if int==0 then lift_coroutine coroutine else lift_coroutine (Fork {int=int,coroutine=coroutine,coroutine_sequence=other_coroutine})

do_race::Dynamic_int a->Int->Raw_coroutine a ()->Raw_coroutine a ()
do_race dynamic_int int raw_coroutine=let coroutine_sequence=raw_coroutine.coroutine_sequence in case coroutine_sequence of
    DS.Empty->do_empty
    coroutine DS.:<| other_coroutine->let new_int=DS.length other_coroutine in if new_int==0 then lift_coroutine coroutine else lift_coroutine (Race {dynamic_int=dynamic_int,first_int=int,second_int=new_int+1,coroutine_sequence=coroutine_sequence})

from_coroutine::Coroutine a->(DIM.IntMap (Linear_coroutine a),Int)
from_coroutine coroutine=let (linear_coroutine,int_index,code_index)=from_coroutine_a coroutine 1 0 0 DIM.empty in (DIM.insert code_index Linear_end linear_coroutine,int_index)

from_coroutine_a::Coroutine a->Int->Int->Int->DIM.IntMap (Linear_coroutine a)->(DIM.IntMap (Linear_coroutine a),Int,Int)
from_coroutine_a this_coroutine clone_number code_index int_index linear_coroutine=case this_coroutine of
    Done->(linear_coroutine,int_index,code_index)
    Emit {emit}->(DIM.insert code_index (Linear_emit {emit=emit}) linear_coroutine,int_index,code_index+1)
    Wait {dynamic_int}->(DIM.insert (code_index+1) (Linear_wait {int_index=int_index}) (DIM.insert code_index (Linear_dynamic_int {int_index=int_index,dynamic_int=dynamic_int}) linear_coroutine),int_index+clone_number,code_index+2)
    Forever {coroutine}->let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number code_index int_index linear_coroutine in (DIM.insert new_code_index (Linear_jump {code_index=code_index}) new_linear_coroutine,new_int_index,new_code_index+1)
    Then {coroutine_sequence}->DF.foldl' (\(this_linear_coroutine,this_int_index,this_code_index) coroutine->let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number this_code_index int_index this_linear_coroutine in (new_linear_coroutine,max this_int_index new_int_index,new_code_index)) (linear_coroutine,int_index,code_index) coroutine_sequence
    While {dynamic_bool,coroutine}->let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number (code_index+1) int_index linear_coroutine in let end_code_index=new_code_index+1 in (DIM.insert new_code_index (Linear_jump {code_index=code_index}) (DIM.insert code_index (Linear_false_jump {code_index=end_code_index,dynamic_bool=dynamic_bool}) new_linear_coroutine),new_int_index,end_code_index)
    Pause {dynamic_bool,coroutine}->let body_code_index=code_index+3 in let countdown_int_index=int_index+clone_number in let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number body_code_index (int_index+2*clone_number) linear_coroutine in let loop_code_index=new_code_index+2 in let yield_code_index=loop_code_index+3 in let jump_code_index=loop_code_index+5 in (DIM.insert jump_code_index (Linear_kill_group {int_index=int_index,int=1}) (DIM.insert (loop_code_index+4) (Linear_jump {code_index=loop_code_index}) (DIM.insert yield_code_index Linear_yield (DIM.insert (loop_code_index+2) (Linear_wake {int_index=int_index}) (DIM.insert (loop_code_index+1) (Linear_true_jump {code_index=yield_code_index,dynamic_bool=dynamic_bool}) (DIM.insert loop_code_index (Linear_less_jump {int_index=countdown_int_index,code_index=jump_code_index,int=1}) (DIM.insert (new_code_index+1) Linear_end (DIM.insert new_code_index (Linear_countdown {int_index=countdown_int_index}) (DIM.insert (code_index+2) (Linear_jump {code_index=loop_code_index}) (DIM.insert (code_index+1) (Linear_create_group {int_index=int_index,group_code_index=DIM.singleton 0 body_code_index,int=1}) (DIM.insert code_index (Linear_int {int_index=countdown_int_index,int=1}) new_linear_coroutine)))))))))),new_int_index,loop_code_index+6)
    Skip {dynamic_bool,coroutine}->let body_code_index=code_index+3 in let countdown_int_index=int_index+clone_number in let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number body_code_index (int_index+2*clone_number) linear_coroutine in let loop_code_index=new_code_index+2 in let jump_code_index=loop_code_index+5 in (DIM.insert jump_code_index (Linear_kill_group {int_index=int_index,int=1}) (DIM.insert (loop_code_index+4) (Linear_jump {code_index=loop_code_index}) (DIM.insert (loop_code_index+3) Linear_yield (DIM.insert (loop_code_index+2) (Linear_wake {int_index=int_index}) (DIM.insert (loop_code_index+1) (Linear_true_jump {code_index=jump_code_index,dynamic_bool=dynamic_bool}) (DIM.insert loop_code_index (Linear_less_jump {int_index=countdown_int_index,code_index=jump_code_index,int=1}) (DIM.insert (new_code_index+1) Linear_end (DIM.insert new_code_index (Linear_countdown {int_index=countdown_int_index}) (DIM.insert (code_index+2) (Linear_jump {code_index=loop_code_index}) (DIM.insert (code_index+1) (Linear_create_group {int_index=int_index,group_code_index=DIM.singleton 0 body_code_index,int=1}) (DIM.insert code_index (Linear_int {int_index=countdown_int_index,int=1}) new_linear_coroutine)))))))))),new_int_index,loop_code_index+6)
    Repeat {dynamic_int,coroutine}->let loop_code_index=code_index+2 in let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number loop_code_index (int_index+clone_number) linear_coroutine in let end_code_index=new_code_index+1 in (DIM.insert new_code_index (Linear_one_more_jump {int_index=int_index,code_index=loop_code_index}) (DIM.insert (code_index+1) (Linear_one_less_jump {int_index=int_index,code_index=end_code_index}) (DIM.insert code_index (Linear_dynamic_int {int_index=int_index,dynamic_int=dynamic_int}) new_linear_coroutine)),new_int_index,end_code_index)
    Clone {int,coroutine}->let new_int=int-1 in if new_int<0 then (linear_coroutine,int_index,code_index) else let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine (int*clone_number) (code_index+1) (int_index+clone_number) linear_coroutine in (DIM.insert new_code_index (Linear_clone_kill {int_index=int_index,clone_number=clone_number}) (DIM.insert code_index (Linear_clone {int_index=int_index,clone_number=clone_number,int=new_int}) new_linear_coroutine),new_int_index,new_code_index+1)
    If {dynamic_bool,first_coroutine,second_coroutine}->let (first_linear_coroutine,first_int_index,first_code_index)=from_coroutine_a first_coroutine clone_number (code_index+1) int_index linear_coroutine in let new_code_index=first_code_index+1 in let (second_linear_coroutine,second_int_index,second_code_index)=from_coroutine_a second_coroutine clone_number new_code_index int_index first_linear_coroutine in (DIM.insert first_code_index (Linear_jump {code_index=second_code_index}) (DIM.insert code_index (Linear_false_jump {code_index=new_code_index,dynamic_bool=dynamic_bool}) second_linear_coroutine),max first_int_index second_int_index,second_code_index)
    Dynamic_clone {dynamic_int,int,coroutine}->let new_int=int-1 in if new_int<0 then (linear_coroutine,int_index,code_index) else let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine (int*clone_number) (code_index+1) (int_index+clone_number) linear_coroutine in let kill_code_index=new_code_index+1 in (DIM.insert new_code_index (Linear_clone_kill {int_index=int_index,clone_number=clone_number}) (DIM.insert code_index (Linear_dynamic_clone {int_index=int_index,code_index=kill_code_index,clone_number=clone_number,dynamic_int=dynamic_int,int=new_int}) new_linear_coroutine),new_int_index,kill_code_index)
    Case {dynamic_int,int,coroutine_sequence}->let (new_linear_coroutine,new_int_index,new_code_index,single_linear_coroutine)=case_coroutine DIM.empty DIS.empty coroutine_sequence int 0 (int_index+clone_number) clone_number (code_index+2) int_index linear_coroutine in (DIM.insert (code_index+1) single_linear_coroutine (DIM.insert code_index (Linear_dynamic_int {int_index=int_index,dynamic_int=dynamic_int}) new_linear_coroutine),new_int_index,new_code_index)
    Fork {int,coroutine,coroutine_sequence}->let body_code_index=code_index+1 in let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number (body_code_index+int) (int_index+clone_number) linear_coroutine in let (final_linear_coroutine,final_int_index,final_code_index)=fork_coroutine DIS.empty coroutine_sequence body_code_index clone_number (new_code_index+1) new_int_index (DIM.insert code_index (Linear_int {int_index=int_index,int=int}) new_linear_coroutine) in (DIM.insert final_code_index (Linear_fork_kill {int_index=int_index}) final_linear_coroutine,final_int_index,final_code_index+1)
    Race {dynamic_int,first_int,second_int,coroutine_sequence}->let countdown_int_index=int_index+clone_number in let (new_linear_coroutine,new_int_index,new_code_index,group_code_index)=race_coroutine coroutine_sequence 0 countdown_int_index clone_number (code_index+3) (int_index+2*clone_number) linear_coroutine in let kill_code_index=new_code_index+4 in (DIM.insert kill_code_index (Linear_kill_group {int_index=int_index,int=second_int}) (DIM.insert (new_code_index+3) (Linear_jump {code_index=new_code_index}) (DIM.insert (new_code_index+2) Linear_yield (DIM.insert (new_code_index+1) (Linear_wake_group {int_index=int_index,dynamic_int=dynamic_int,int=second_int}) (DIM.insert new_code_index (Linear_less_jump {int_index=countdown_int_index,code_index=kill_code_index,int=second_int-first_int+1}) (DIM.insert (code_index+2) (Linear_jump {code_index=new_code_index}) (DIM.insert (code_index+1) (Linear_create_group {int_index=int_index,group_code_index=group_code_index,int=second_int}) (DIM.insert code_index (Linear_int {int_index=countdown_int_index,int=second_int}) new_linear_coroutine))))))),new_int_index,new_code_index+5)

case_coroutine::DIM.IntMap Int->DIS.IntSet->DS.Seq (Coroutine a)->Int->Int->Int->Int->Int->Int->DIM.IntMap (Linear_coroutine a)->(DIM.IntMap (Linear_coroutine a),Int,Int,Linear_coroutine a)
case_coroutine case_code_index jump_code_index coroutine_sequence int index max_int_index clone_number code_index int_index linear_coroutine=case coroutine_sequence of
    DS.Empty->let (new_linear_coroutine,new_code_index)=case_coroutine_a case_code_index int 0 code_index int_index linear_coroutine in (DIS.foldl' (\this_linear_coroutine this_code_index->DIM.insert this_code_index (Linear_jump {code_index=new_code_index}) this_linear_coroutine) new_linear_coroutine jump_code_index,max_int_index,new_code_index,Linear_jump {code_index=code_index})
    coroutine DS.:<| other_coroutine->let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number code_index (int_index+clone_number) linear_coroutine in case_coroutine (DIM.insert index code_index case_code_index) (DIS.insert new_code_index jump_code_index) other_coroutine int (index+1) (max new_int_index max_int_index) clone_number (new_code_index+1) int_index new_linear_coroutine

case_coroutine_a::DIM.IntMap Int->Int->Int->Int->Int->DIM.IntMap (Linear_coroutine a)->(DIM.IntMap (Linear_coroutine a),Int)
case_coroutine_a case_code_index int index code_index int_index linear_coroutine=case int of
    1->(DIM.insert code_index (Linear_jump {code_index=intmap_lookup index case_code_index}) linear_coroutine,code_index+1)
    _->let half_int=div int 2 in let new_int=index+half_int in let (right_linear_coroutine,right_code_index)=case_coroutine_a case_code_index (int-half_int) new_int (code_index+1) int_index linear_coroutine in let (left_linear_coroutine,left_code_index)=case_coroutine_a case_code_index half_int index right_code_index int_index right_linear_coroutine in (DIM.insert code_index (Linear_less_jump {int_index=int_index,code_index=right_code_index,int=new_int}) left_linear_coroutine,left_code_index)

fork_coroutine::DIS.IntSet->DS.Seq (Coroutine a)->Int->Int->Int->Int->DIM.IntMap (Linear_coroutine a)->(DIM.IntMap (Linear_coroutine a),Int,Int)
fork_coroutine jump_code_index coroutine_sequence fork_code_index clone_number code_index int_index linear_coroutine=case coroutine_sequence of
    DS.Empty->let new_code_index=code_index-1 in (DIS.foldl' (\this_linear_coroutine this_code_index->DIM.insert this_code_index (Linear_jump {code_index=new_code_index}) this_linear_coroutine) linear_coroutine jump_code_index,int_index,new_code_index)
    coroutine DS.:<| other_coroutine->let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number code_index int_index linear_coroutine in fork_coroutine (DIS.insert (code_index-1) jump_code_index) other_coroutine (fork_code_index+1) clone_number (new_code_index+1) new_int_index (DIM.insert fork_code_index (Linear_fork {code_index=code_index}) new_linear_coroutine)

race_coroutine::DS.Seq (Coroutine a)->Int->Int->Int->Int->Int->DIM.IntMap (Linear_coroutine a)->(DIM.IntMap (Linear_coroutine a),Int,Int,DIM.IntMap Int)
race_coroutine coroutine_sequence index countdown_int_index clone_number code_index int_index linear_coroutine=case coroutine_sequence of
    DS.Empty->(linear_coroutine,int_index,code_index,DIM.empty)
    coroutine DS.:<| other_coroutine->let (new_linear_coroutine,new_int_index,new_code_index)=from_coroutine_a coroutine clone_number code_index int_index linear_coroutine in let (final_linear_coroutine,final_int_index,final_code_index,group_code_index)=race_coroutine other_coroutine (index+1) countdown_int_index clone_number (new_code_index+2) (max int_index new_int_index) (DIM.insert (new_code_index+1) Linear_end (DIM.insert new_code_index (Linear_countdown {int_index=countdown_int_index}) new_linear_coroutine)) in (final_linear_coroutine,final_int_index,final_code_index,DIM.insert index code_index group_code_index)

run_coroutine::DIM.IntMap (Linear_coroutine a)->Int->Int->DS.Seq Int->DS.Seq Int->DS.Seq Int->DIM.IntMap (DS.Seq Int)->DIM.IntMap Program_counter->DIM.IntMap Int->Engine a->Widget a->(Widget a,Engine a,DIM.IntMap Int,DIM.IntMap Program_counter,DIM.IntMap (DS.Seq Int),DS.Seq Int,Int,Int)
run_coroutine linear_coroutine program_counter_index index_group_index survived_main_index_group newborn_main_index_group main_index_group index_group program_counter variable engine widget=case newborn_main_index_group of
    DS.Empty->case main_index_group of
        DS.Empty->(widget,engine,variable,program_counter,index_group,survived_main_index_group,index_group_index,program_counter_index)
