    Linear_emit {emit}->let (new_widget,new_engine)=emit engine widget in run_coroutine_a linear_coroutine main_index clone_index (this_code_index+1) program_counter_index index_group_index survived_main_index_group newborn_main_index_group main_index_group index_group program_counter variable new_engine new_widget
    Linear_wait {int_index}->let (new_variable,int)=intmap_update_lookup (int_index+clone_index) (\this_int->this_int-1) variable in if 0<int then run_coroutine linear_coroutine program_counter_index index_group_index (survived_main_index_group DS.|> main_index) newborn_main_index_group main_index_group index_group (intmap_insert main_index (Program_counter {code_index=this_code_index,clone_index=clone_index}) program_counter) new_variable engine widget else run_coroutine_a linear_coroutine main_index clone_index (this_code_index+1) program_counter_index index_group_index survived_main_index_group newborn_main_index_group main_index_group index_group program_counter new_variable engine widget
    Linear_countdown {int_index}->run_coroutine_a linear_coroutine main_index clone_index (this_code_index+1) program_counter_index index_group_index survived_main_index_group newborn_main_index_group main_index_group index_group program_counter (intmap_update (int_index+clone_index) (\int->int-1) variable) engine widget
    Linear_fork_kill {int_index}->let (new_variable,int)=intmap_update_lookup (int_index+clone_index) (\this_int->this_int-1) variable in if 0<int then run_coroutine linear_coroutine program_counter_index index_group_index survived_main_index_group newborn_main_index_group main_index_group index_group program_counter new_variable engine widget else run_coroutine_a linear_coroutine main_index clone_index (this_code_index+1) program_counter_index index_group_index survived_main_index_group newborn_main_index_group main_index_group index_group program_counter new_variable engine widget
